declarations.code:
private def uniformRegularityValues {F : Type*} (variation : F → Measure K)
    (A : Set F) : Set ℝ :=
  {r | ∃ U : ℕ → Set K, (∀ n, IsOpen (U n)) ∧ Pairwise (Disjoint on U) ∧
    ∃ φ : ℕ → F, (∀ n, φ n ∈ A) ∧ r = ⨅ n, (variation (φ n)).real (U n)}

